#include "unit.h"
#include "platform/archive.h"

// The zip and gz fixtures below were produced by a known-good compressor (python zipfile/gzip), so
// they exercise the inflate in archive.c against real DEFLATE streams rather than its own output.

#define PAYLOAD_SIZE 16384

static void fill_payload(unsigned char *p) {
  for (int i = 0; i < PAYLOAD_SIZE; i++) p[i] = (unsigned char)((i / 64) + (i % 7) * 37);
}

