// Fixtures go to a scratch file in the temp directory, so running this by hand leaves nothing behind.
static const char *write_tmp(const unsigned char *data, size_t n, const char *name) {
  static char path[512];
  const char *dir = getenv("TMPDIR");
  if (!dir || !*dir) dir = getenv("TEMP");
  if (!dir || !*dir) dir = "/tmp";
  size_t len = strlen(dir);
  const char *sep = len && (dir[len - 1] == '/' || dir[len - 1] == '\\\\') ? "" : "/";
  snprintf(path, sizeof path, "%s%stest_archive_%s", dir, sep, name);
  FILE *f = fopen(path, "wb");
  ASSERT(f);
  ASSERT_EQ(fwrite(data, 1, n, f), n);
  fclose(f);
  return path;
}

static void unlink_tmp(const char *name) {
  char path[512];
  const char *dir = getenv("TMPDIR");
  if (!dir || !*dir) dir = getenv("TEMP");
  if (!dir || !*dir) dir = "/tmp";
  size_t len = strlen(dir);
  const char *sep = len && (dir[len - 1] == '/' || dir[len - 1] == '\\\\') ? "" : "/";
  snprintf(path, sizeof path, "%s%stest_archive_%s", dir, sep, name);
  remove(path);
}

// Unpacks a fixture and checks it came back byte for byte.
static void expect_payload(const unsigned char *fixture, size_t n, const char *name) {
  static unsigned char want[PAYLOAD_SIZE];
  fill_payload(want);
  char err[40] = {0};
  size_t got_size = 0;
  unsigned char *got = archive_read_rom(write_tmp(fixture, n, name), &got_size, err, sizeof err);
  ASSERT(got);
  ASSERT_EQ(err[0], 0);
  ASSERT_EQ(got_size, PAYLOAD_SIZE);
  ASSERT_EQ(memcmp(got, want, PAYLOAD_SIZE), 0);
  free(got);
}

static void deflated_zip_picks_the_rom_by_name(void) { expect_payload(fx_zip_named, sizeof fx_zip_named, "named.zip"); }
static void stored_zip_is_copied_out(void) { expect_payload(fx_zip_stored, sizeof fx_zip_stored, "stored.zip"); }
static void unnamed_zip_falls_back_to_the_largest(void) { expect_payload(fx_zip_largest, sizeof fx_zip_largest, "largest.zip"); }
static void gzip_is_unpacked(void) { expect_payload(fx_gz, sizeof fx_gz, "rom.gz"); }

// A loose ROM has no container and must come back untouched.
static void a_plain_file_is_read_as_is(void) {
  static unsigned char want[PAYLOAD_SIZE];
  fill_payload(want);
  char err[40] = {0};
  size_t n = 0;
  unsigned char *got = archive_read_rom(write_tmp(want, sizeof want, "plain.gbc"), &n, err, sizeof err);
  ASSERT(got);
  ASSERT_EQ(n, PAYLOAD_SIZE);
  ASSERT_EQ(memcmp(got, want, PAYLOAD_SIZE), 0);
  free(got);
}

// The extension is only a hint: a ROM saved as .zip still loads.
static void the_magic_wins_over_the_extension(void) {
  static unsigned char want[PAYLOAD_SIZE];
  fill_payload(want);
  char err[40] = {0};
  size_t n = 0;
  unsigned char *got = archive_read_rom(write_tmp(want, sizeof want, "mislabelled.zip"), &n, err, sizeof err);
  ASSERT(got);
  ASSERT_EQ(n, PAYLOAD_SIZE);
  free(got);
}

static void sevenzip_is_refused_with_a_reason(void) {
  static const unsigned char sevenzip[] = {0x37, 0x7a, 0xbc, 0xaf, 0x27, 0x1c, 0, 4, 1, 2, 3, 4};
  char err[40] = {0};
  size_t n = 0;
  ASSERT(!archive_read_rom(write_tmp(sevenzip, sizeof sevenzip, "rom.7z"), &n, err, sizeof err));
  ASSERT(err[0]);
  ASSERT(strstr(err, "7Z"));
}

// Detection is by content, so a 7z under another name explains itself too.
static void a_renamed_sevenzip_is_still_recognised(void) {
  static const unsigned char sevenzip[] = {0x37, 0x7a, 0xbc, 0xaf, 0x27, 0x1c, 0, 4, 9, 9, 9, 9};
  char err[40] = {0};
  size_t n = 0;
  ASSERT(!archive_read_rom(write_tmp(sevenzip, sizeof sevenzip, "renamed.gbc"), &n, err, sizeof err));
  ASSERT(strstr(err, "7Z"));
}

static void a_missing_file_reports_a_reason(void) {
  char err[40] = {0};
  size_t n = 0;
  ASSERT(!archive_read_rom("test_archive_does_not_exist", &n, err, sizeof err));
  ASSERT(err[0]);
}

// A truncated archive must fail rather than read past the buffer or loop.
static void a_damaged_zip_is_refused(void) {
  char err[40] = {0};
  size_t n = 0;
  ASSERT(!archive_read_rom(write_tmp(fx_zip_named, sizeof fx_zip_named / 2, "cut.zip"), &n, err, sizeof err));
  ASSERT(err[0]);
}

static void a_damaged_gz_is_refused(void) {
  char err[40] = {0};
  size_t n = 0;
  ASSERT(!archive_read_rom(write_tmp(fx_gz, 40, "cut.gz"), &n, err, sizeof err));
  ASSERT(err[0]);
}

int main(void) {
  RUN(deflated_zip_picks_the_rom_by_name);
  RUN(stored_zip_is_copied_out);
  RUN(unnamed_zip_falls_back_to_the_largest);
  RUN(gzip_is_unpacked);
  RUN(a_plain_file_is_read_as_is);
  RUN(the_magic_wins_over_the_extension);
  RUN(sevenzip_is_refused_with_a_reason);
  RUN(a_renamed_sevenzip_is_still_recognised);
  RUN(a_missing_file_reports_a_reason);
  RUN(a_damaged_zip_is_refused);
  RUN(a_damaged_gz_is_refused);
  unlink_tmp("named.zip");
  unlink_tmp("stored.zip");
  unlink_tmp("largest.zip");
  unlink_tmp("rom.gz");
  unlink_tmp("plain.gbc");
  unlink_tmp("mislabelled.zip");
  unlink_tmp("rom.7z");
  unlink_tmp("renamed.gbc");
  unlink_tmp("cut.zip");
  unlink_tmp("cut.gz");
  return 0;
}
